# Generated by tack build. Do not edit. Codex runs each tack hook as
# sh run-hook.sh <script>. Codex lets a call run when a hook exits 127 or
# crashes, so a missing node, or a node that exits nonzero or dies, becomes
# exit 2 with a named reason on stderr, which Codex treats as a block. On
# success the script's stdout passes through unchanged.

script=$1

if ! command -v node >/dev/null 2>&1; then
  echo 'tack: node_missing' >&2
  exit 2
fi

# An inner sh runs and reaps node with its stderr closed off, so a shell's
# notice of a node killed by a signal ("Segmentation fault") goes nowhere,
# and it turns a signal into a plain exit 1 the outer shell sees normally.
# shellcheck disable=SC2016 # $1 expands in the inner sh, not here.
output=$(sh -c 'node "$1" 2>/dev/null; s=$?; if [ "$s" -gt 128 ]; then exit 1; fi; exit "$s"' sh "$script" 2>/dev/null)
status=$?

if [ "$status" -ne 0 ]; then
  echo 'tack: node_failed' >&2
  exit 2
fi

if [ -n "$output" ]; then
  printf '%s\n' "$output"
fi

exit 0
